<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Usecase\Retrieve\SmtpOutboundConfigRetrieveUsecase;
use Civi\Lughauth\Shared\Security\AesCypherService;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Usecase\Retrieve\SmtpOutboundConfigRetrieveResult;

class SmtpOutboundConfigRetrieveController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SmtpOutboundConfigRetrieveUsecase $retrieveUsecase,
        private readonly AesCypherService $cypherService,
    ) {
    }
    #[OA\Get(
        path: "/api/template/smtp-outbound-config{uid}",
        tags: ["Smtp outbound config"],
        description:"Create",
        parameters: [
               new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
          ],
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/SmtpOutboundConfigApiDTO")),
              new OA\Response(response: 404, description: "Not found"),
          ]
    )]
    public function retrieve(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Retrieve Smtp outbound config");
        $span = $this->startSpan("Retrieve Smtp outbound config");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->retrieveUsecase->retrieve($uid);
            $value = $this->mapSmtpOutboundConfig($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapSmtpOutboundConfig(ServerRequestInterface $request, SmtpOutboundConfigRetrieveResult $value): SmtpOutboundConfigApiDTO
    {
        $this->logDebug("Map entity to output dto for Smtp outbound config");
        $span = $this->startSpan("Map entity to output dto for Smtp outbound config");
        try {
            $tenant = $value->getTenant();
            $dto = new SmtpOutboundConfigApiDTO();
            $dto->uid = $value->getUid();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->host = $value->getHost();
            $dto->port = $value->isPort();
            $dto->login = $value->getLogin();
            $dto->password = '******';
            $dto->senderName = $value->getSenderName();
            $dto->senderEmail = $value->getSenderEmail();
            $dto->timeout = $value->getTimeout();
            $dto->useTls = $value->isUseTls();
            $dto->maxRetries = $value->getMaxRetries();
            $dto->retryDelay = $value->getRetryDelay();
            $dto->rateLimit = $value->getRateLimit();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
